wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(3414917000351307)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'pc_insere_anexo'
,p_process_sql_clob=>wwv_flow_utilities.join(wwv_flow_t_varchar2(
'declare',
'  w_user_st_atualiza varchar2(30);',
'  w_user_dt_atualiza date;',
'  w_anex_in_id       integer;',
'  W_BLOB_CONTENT          BLOB;',
'  W_NAME                            APEX_APPLICATION_TEMP_FILES.NAME%TYPE;',
'  W_FILENAME                     APEX_APPLICATION_TEMP_FILES.FILENAME%TYPE;',
'  W_MIME_TYPE                  APEX_APPLICATION_TEMP_FILES.MIME_TYPE%TYPE;',
'  W_TAMANHO                   NUMBER;',
'  ',
'  CURSOR C_CONTENT IS',
'  SELECT BLOB_CONTENT, NAME, FILENAME, MIME_TYPE, DBMS_LOB.GETLENGTH(BLOB_CONTENT) TAMANHO ',
'    FROM APEX_APPLICATION_TEMP_FILES',
'   WHERE NAME = :P21_NAME',
'         AND DBMS_LOB.GETLENGTH(BLOB_CONTENT) < (1024*1024);',
'begin',
'  pc_atualiza_usuario(w_user_st_atualiza, w_user_dt_atualiza);',
'  select sq_anexo.nextval into w_anex_in_id from dual;',
'  OPEN C_CONTENT;',
'  FETCH C_CONTENT INTO W_BLOB_CONTENT, W_NAME, W_FILENAME, W_MIME_TYPE, W_TAMANHO;',
'  CLOSE C_CONTENT;',
'  insert into tbl_anexo(anex_in_id, ',
'                        anex_st_nome_imagem, ',
'                        anex_st_nome_arquivo,',
'                        anex_st_mime_type,',
'                        anex_bl_conteudo,',
'                        anex_nu_tamanho,',
'                        user_st_atualiza,',
'                        user_dt_atualiza)',
'               values  (w_anex_in_id,',
'                        :P21_NAME,',
'                        W_FILENAME,',
'                        W_MIME_TYPE,',
'                        W_BLOB_CONTENT,',
'                        W_TAMANHO,',
'                        W_USER_ST_ATUALIZA,',
'                        W_USER_DT_ATUALIZA);',
'    pc_vincula_anexo(W_ANEX_IN_ID, ''ALUNO'',:P21_ALU_IN_ID);',
'end;'))
,p_process_error_message=>'Falha ao tentar criar o anexo!'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_api.id(3411540957293017)
,p_process_when=>'P21_NAME'
,p_process_when_type=>'ITEM_IS_NOT_NULL'
,p_process_success_message=>'Anexo criado com sucesso!'
);
